use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;
$jobId=$argv[1]??'';$em=DoctrineEntityManagerFactory::create();$job=$em->find(QuestionPdfImportJobRecord::class,$jobId);if(!$job instanceof QuestionPdfImportJobRecord)throw new RuntimeException('Job não encontrado.');$pages=(new PdftotextPdfTextExtractor())->extractPages($job->documentPath);$questions=$em->createQueryBuilder()->select('q')->from(QuestionRecord::class,'q')->where('q.sourcePdfJobId=:job')->andWhere('q.correctOptionId IS NULL')->setParameter('job',$jobId)->getQuery()->getResult();$updated=0;$unresolved=[];foreach($questions as $question){$page=(int)(($question->sourcePdfPages??[1])[0]??1);$context=implode("\n",array_slice($pages,max(0,$page-1),8));$needle=mb_substr(normalize($question->statement),0,90);$normalized=normalize($context);$at=mb_stripos($normalized,$needle);if($at===false){$unresolved[]=$question->id;continue;}$tail=mb_substr($normalized,$at,18000);$next=preg_match('/\n\s*\d{1,3}\.\s*(?:\(|[A-Z])/u',$tail,$nextMatch,PREG_OFFSET_CAPTURE)?$nextMatch[0][1]:mb_strlen($tail);$section=mb_substr($tail,0,$next);if(!preg_match('/gabarito\s*:\s*(?:letra\s*)?([a-e])\b/iu',$section,$answer)){$unresolved[]=$question->id;continue;}$option=$em->createQueryBuilder()->select('o')->from(QuestionOptionRecord::class,'o')->where('o.questionId=:question')->andWhere('o.label=:label')->setParameter('question',$question->id)->setParameter('label',strtoupper($answer[1]))->getQuery()->getOneOrNullResult();if(!$option instanceof QuestionOptionRecord){$unresolved[]=$question->id;continue;}$question->correctOptionId=$option->id;$question->answerKeySource='OFFICIAL';$question->updatedAt=new DateTimeImmutable('now');$updated++;}$em->flush();echo json_encode(['updated_official'=>$updated,'unresolved'=>count($unresolved),'ids'=>$unresolved],JSON_UNESCAPED_UNICODE).PHP_EOL;function normalize(string $v):string{$v=mb_strtolower($v);$v=str_replace(["\n","\r","-"],' ',$v);return (string)preg_replace('/\s+/u',' ',trim($v));}
